// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Start a session for an existing account.
	// (POST /api/v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout End this session. Needs a session.
	// (POST /api/v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetCurrentUser The account of this session. Needs a session.
	// (GET /api/v1/auth/me)
	GetCurrentUser(ctx context.Context, request GetCurrentUserRequestObject) (GetCurrentUserResponseObject, error)
	// ChangePassword Change the password. Needs a session.
	// (POST /api/v1/auth/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// Register Create an account and start a session.
	// (POST /api/v1/auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// DeleteChannel Delete a channel with its messages and attachments. Admin or owner.
	// (DELETE /api/v1/channels/{channelId})
	DeleteChannel(ctx context.Context, request DeleteChannelRequestObject) (DeleteChannelResponseObject, error)
	// GetChannel One channel. Needs membership in its server.
	// (GET /api/v1/channels/{channelId})
	GetChannel(ctx context.Context, request GetChannelRequestObject) (GetChannelResponseObject, error)
	// UpdateChannel Rename a channel, change its topic or its write access. Admin or owner.
	// (PATCH /api/v1/channels/{channelId})
	UpdateChannel(ctx context.Context, request UpdateChannelRequestObject) (UpdateChannelResponseObject, error)
	// ListMessages A page of history, newest first. Needs membership in the server.
	// (GET /api/v1/channels/{channelId}/messages)
	ListMessages(ctx context.Context, request ListMessagesRequestObject) (ListMessagesResponseObject, error)
	// SendMessage Send a message. Needs the right to write in the channel.
	// (POST /api/v1/channels/{channelId}/messages)
	SendMessage(ctx context.Context, request SendMessageRequestObject) (SendMessageResponseObject, error)
	// DeleteMessage Delete your own message.
	// (DELETE /api/v1/messages/{messageId})
	DeleteMessage(ctx context.Context, request DeleteMessageRequestObject) (DeleteMessageResponseObject, error)
	// EditMessage Edit your own message.
	// (PATCH /api/v1/messages/{messageId})
	EditMessage(ctx context.Context, request EditMessageRequestObject) (EditMessageResponseObject, error)
	// RemoveReaction Take your reaction back.
	// (DELETE /api/v1/messages/{messageId}/reactions/{emoji})
	RemoveReaction(ctx context.Context, request RemoveReactionRequestObject) (RemoveReactionResponseObject, error)
	// AddReaction React to a message. Needs the right to write in the channel.
	// (PUT /api/v1/messages/{messageId}/reactions/{emoji})
	AddReaction(ctx context.Context, request AddReactionRequestObject) (AddReactionResponseObject, error)
	// CreateVoiceToken Issue a LiveKit token for one voice room (development only).
	// (POST /api/v1/voice/token)
	CreateVoiceToken(ctx context.Context, request CreateVoiceTokenRequestObject) (CreateVoiceTokenResponseObject, error)
	// ListWorkspaces The servers this account belongs to, with its role in each. Needs a session.
	// (GET /api/v1/workspaces)
	ListWorkspaces(ctx context.Context, request ListWorkspacesRequestObject) (ListWorkspacesResponseObject, error)
	// CreateWorkspace Create a server. Needs a session.
	// (POST /api/v1/workspaces)
	CreateWorkspace(ctx context.Context, request CreateWorkspaceRequestObject) (CreateWorkspaceResponseObject, error)
	// DeleteWorkspace Delete a server with everything in it. Owner only.
	// (DELETE /api/v1/workspaces/{workspaceId})
	DeleteWorkspace(ctx context.Context, request DeleteWorkspaceRequestObject) (DeleteWorkspaceResponseObject, error)
	// GetWorkspace One server and the caller's role in it. Needs membership.
	// (GET /api/v1/workspaces/{workspaceId})
	GetWorkspace(ctx context.Context, request GetWorkspaceRequestObject) (GetWorkspaceResponseObject, error)
	// UpdateWorkspace Rename a server. Admin or owner.
	// (PATCH /api/v1/workspaces/{workspaceId})
	UpdateWorkspace(ctx context.Context, request UpdateWorkspaceRequestObject) (UpdateWorkspaceResponseObject, error)
	// ListWorkspaceBans Who is banned from this server. Admin or owner.
	// (GET /api/v1/workspaces/{workspaceId}/bans)
	ListWorkspaceBans(ctx context.Context, request ListWorkspaceBansRequestObject) (ListWorkspaceBansResponseObject, error)
	// UnbanWorkspaceMember Lift a ban. Admin or owner.
	// (DELETE /api/v1/workspaces/{workspaceId}/bans/{userId})
	UnbanWorkspaceMember(ctx context.Context, request UnbanWorkspaceMemberRequestObject) (UnbanWorkspaceMemberResponseObject, error)
	// BanWorkspaceMember Ban someone from a server. Admin or owner.
	// (PUT /api/v1/workspaces/{workspaceId}/bans/{userId})
	BanWorkspaceMember(ctx context.Context, request BanWorkspaceMemberRequestObject) (BanWorkspaceMemberResponseObject, error)
	// ListChannels Channels of a server, in their order. Needs membership.
	// (GET /api/v1/workspaces/{workspaceId}/channels)
	ListChannels(ctx context.Context, request ListChannelsRequestObject) (ListChannelsResponseObject, error)
	// CreateChannel Create a channel. Admin or owner.
	// (POST /api/v1/workspaces/{workspaceId}/channels)
	CreateChannel(ctx context.Context, request CreateChannelRequestObject) (CreateChannelResponseObject, error)
	// ReorderChannels Set the order of the channels. Admin or owner.
	// (PUT /api/v1/workspaces/{workspaceId}/channels/order)
	ReorderChannels(ctx context.Context, request ReorderChannelsRequestObject) (ReorderChannelsResponseObject, error)
	// ListWorkspaceMembers Members of a server and their roles. Needs membership.
	// (GET /api/v1/workspaces/{workspaceId}/members)
	ListWorkspaceMembers(ctx context.Context, request ListWorkspaceMembersRequestObject) (ListWorkspaceMembersResponseObject, error)
	// RemoveWorkspaceMember Remove a member. Admin or owner; anyone may remove themselves.
	// (DELETE /api/v1/workspaces/{workspaceId}/members/{userId})
	RemoveWorkspaceMember(ctx context.Context, request RemoveWorkspaceMemberRequestObject) (RemoveWorkspaceMemberResponseObject, error)
	// SetWorkspaceMemberRole Change a member's role. Owner only.
	// (PATCH /api/v1/workspaces/{workspaceId}/members/{userId})
	SetWorkspaceMemberRole(ctx context.Context, request SetWorkspaceMemberRoleRequestObject) (SetWorkspaceMemberRoleResponseObject, error)
	// GetLiveness Liveness probe — the process is running.
	// (GET /healthz)
	GetLiveness(ctx context.Context, request GetLivenessRequestObject) (GetLivenessResponseObject, error)
	// GetReadiness Readiness probe — the instance can serve traffic.
	// (GET /readyz)
	GetReadiness(ctx context.Context, request GetReadinessRequestObject) (GetReadinessResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Login operation middleware
func (sh *strictHandler) Login(w http.ResponseWriter, r *http.Request) {
	var request LoginRequestObject

	var body LoginJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Login(ctx, request.(LoginRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Login")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(LoginResponseObject); ok {
		if err := validResponse.VisitLoginResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

